export type UseButtonOptions = {
	elementType?: "button" | (string & {});
	removeRole?: MaybeRef<boolean>;
	interaction?: UseInteractionsOptions;
};

export function useButton(
	elementRef: Readonly<ShallowRef<HTMLElement | null>>,
	{
		elementType = "button",
		removeRole = false,
		interaction,
	}: UseButtonOptions = {},
) {
	const element = computed<HTMLElement | null>(() => {
		if (elementRef.value && "$el" in elementRef.value) {
			return elementRef.value.$el as HTMLElement | null;
		}
		return elementRef.value;
	});

	const removeRoleRef = toRef(removeRole);

	const interactions = useInteractions(elementRef, interaction);

	watchEffect(() => {
		if (!element.value)
			return;
		if (elementType !== "button") {
			if (removeRoleRef.value) {
				element.value.removeAttribute("role");
			}
			else {
				element.value.setAttribute("role", "button");
			}
			return;
		}
		if (element.value.getAttribute("type"))
			return;
		element.value.setAttribute("type", "button");
	});

	return interactions;
}

import type { MaybeRefOrGetter, Ref } from "vue";
import useEmblaCarouselVue from "embla-carousel-vue";
import { toRef } from "vue";

type UnwrapRef<T> = T extends Ref<infer U> ? U : T;

type EmblaParameters = Parameters<typeof useEmblaCarouselVue>;

type EmblaParameter<T extends number> = UnwrapRef<
	NonNullable<EmblaParameters[T]>
>;

type EmblaReturn = ReturnType<typeof useEmblaCarouselVue>;

export type EmblaOptions = EmblaParameter<0>;
export type EmblaPlugin = EmblaParameter<1>[number];

export type EmblaCarouselApi = NonNullable<UnwrapRef<EmblaReturn[1]>>;

export type UseCarouselOptions = {
	options?: MaybeRefOrGetter<EmblaOptions>;
	plugins?: MaybeRefOrGetter<EmblaPlugin[]>;
};

export function useCarousel(opts: UseCarouselOptions = {}): {
	ref: Ref<HTMLElement | undefined>;
	api: Ref<EmblaCarouselApi | undefined>;
} {
	const options = toRef(opts.options ?? (() => ({})));
	const plugins = toRef(opts.plugins ?? (() => []));

	const [ref, api] = useEmblaCarouselVue(options, plugins);

	return { ref, api };
}

import type { ShallowRef } from "vue";
import {
	useElementHover,
	useFocus,
	useFocusWithin,
	useMousePressed,
	useMutationObserver,
} from "@vueuse/core";
import { computed, ref, watchEffect } from "vue";

export type UseInteractionsOptions = {
	focus?: boolean;
	focusWithin?: boolean;
	focusVisible?: boolean;
	hover?: boolean;
	press?: boolean;
	disabled?: boolean;
};

export function useInteractions(
	elementRef: Readonly<ShallowRef<HTMLElement | null>>,
	{
		focus = true,
		focusWithin = true,
		focusVisible = true,
		hover = true,
		press = true,
		disabled = true,
	}: UseInteractionsOptions = {},
) {
	const element = computed<HTMLElement | null>(() => {
		if (elementRef.value && "$el" in elementRef.value) {
			return elementRef.value.$el as HTMLElement | null;
		}
		return elementRef.value;
	});

	const { focused: inFocus } = useFocus(elementRef);
	const { focused: inFocusWithin } = useFocusWithin(elementRef);
	const { focused: inFocusVisible } = useFocus(elementRef, {
		focusVisible: true,
	});
	const isHovered = useElementHover(elementRef);
	const { pressed: isPressed } = useMousePressed({
		target: elementRef,
	});
	const isDisabledMutation = ref<boolean | undefined>(undefined);
	const isDisabled = computed(() => {
		if (isDisabledMutation.value !== undefined)
			return isDisabledMutation.value;
		if (!element.value)
			return false;
		const isAriaDisabled = element.value.ariaDisabled?.toLowerCase() === "true";
		return (
			(isAriaDisabled || (element.value as HTMLButtonElement).disabled) ?? false
		);
	});

	useMutationObserver(
		elementRef,
		(mutations) => {
			const mutation = mutations[0];
			if (!mutation || mutation.type !== "attributes")
				return;
			const el = mutation.target as HTMLButtonElement;
			const isAriaDisabled = el.ariaDisabled?.toLowerCase() === "true";
			isDisabledMutation.value = (isAriaDisabled || el.disabled) ?? false;
		},
		{
			attributes: true,
		},
	);

	function setData(name: string, value: boolean, isEnabled: boolean) {
		if (!element.value)
			return;
		if (value && isEnabled) {
			element.value.setAttribute(`data-${name}`, `${value}`);
		}
		else if (isEnabled) {
			element.value.removeAttribute(`data-${name}`);
		}
	}

	watchEffect(() => {
		setData("in-focus", inFocus.value, focus);
		setData("in-focus-within", inFocusWithin.value, focusWithin);
		setData("in-focus-visible", inFocusVisible.value, focusVisible);
		setData("is-hovered", isHovered.value, hover);
		setData("is-pressed", isPressed.value, press);
		setData("is-disabled", isDisabled.value, disabled);
	});

	return {
		inFocus,
		inFocusVisible,
		inFocusWithin,
		isHovered,
		isPressed,
		isDisabled,
	};
}

import type { AnimationPlaybackControls } from "motion-v";
import type { ShallowRef } from "vue";
import { useEventListener } from "@vueuse/core";
import { animate } from "motion-v";
import { computed, onUnmounted } from "vue";
import { materialDuration } from "@/config";

export type UseRippleOptions = {
	duration?: number;
	centered?: boolean;
	speedDelta?: number;
};

type RippleState = {
	id: string;
	isAnimationEnded: boolean;
	isPressed: boolean;
	animation: "entering" | "exiting" | null;
};

export function useRipple(
	ref: Readonly<ShallowRef<HTMLElement | null>>,
	options: UseRippleOptions = {},
) {
	const {
		duration = materialDuration["extra-long-4"],
		centered = false,
		speedDelta = 2,
	} = options;

	const element = computed<HTMLElement | null>(() => {
		if (ref.value && "$el" in ref.value) {
			return ref.value.$el as HTMLElement | null;
		}
		return ref.value;
	});

	// Используем Map для управления анимациями
	const activeAnimations = new Map<string, AnimationPlaybackControls>();

	function cleanupAnimation(id: string): void {
		const controls = activeAnimations.get(id);
		if (controls) {
			controls.cancel();
			activeAnimations.delete(id);
		}
	}

	function animateEnter(
		ripple: HTMLElement,
		onComplete: () => void,
	): AnimationPlaybackControls {
		return animate(
			ripple,
			{ "--ripple-scale": 1 },
			{
				duration: (duration * 2) / 1000,
				onComplete,
			},
		);
	}

	function animateExit(
		ripple: HTMLElement,
		onComplete: () => void,
	): AnimationPlaybackControls {
		return animate(
			ripple,
			{ opacity: 0 },
			{
				duration: duration / (speedDelta * 2) / 1000,
				onComplete,
			},
		);
	}

	function getRippleState(ripple: HTMLElement): RippleState {
		return {
			get id(): string {
				return ripple.dataset.id!;
			},
			set id(value: string) {
				ripple.dataset.id = value;
			},
			get isAnimationEnded(): boolean {
				return ripple.dataset.isAnimationEnded === "true";
			},
			set isAnimationEnded(value: boolean) {
				ripple.dataset.isAnimationEnded = String(value);
			},
			get isPressed(): boolean {
				return ripple.dataset.isPressed === "true";
			},
			set isPressed(value: boolean) {
				ripple.dataset.isPressed = String(value);
			},
			get animation(): "entering" | "exiting" | null {
				const anim = ripple.dataset.animation;
				return anim === "entering" || anim === "exiting" ? anim : null;
			},
			set animation(value: "entering" | "exiting" | null) {
				if (value) {
					ripple.dataset.animation = value;
				}
				else {
					delete ripple.dataset.animation;
				}
			},
		};
	}

	function createRipple(
		x: number,
		y: number,
		width: number,
		height: number,
	): [HTMLElement, RippleState] {
		const ripple = document.createElement("span");
		const diameter = Math.max(width, height) * 2;
		const id = `ripple-${crypto.randomUUID()}`;

		ripple.className = "ripple";
		ripple.setAttribute("aria-hidden", "true");
		ripple.style.setProperty("--ripple-x", `${x}px`);
		ripple.style.setProperty("--ripple-y", `${y}px`);
		ripple.style.setProperty("--ripple-diameter", `${diameter}px`);
		ripple.style.setProperty("--ripple-scale", "0");
		ripple.dataset.id = id;
		ripple.dataset.isPressed = "true";
		ripple.dataset.isAnimationEnded = "false";
		ripple.dataset.animation = "entering";

		const state = getRippleState(ripple);
		return [ripple, state];
	}

	function handleRippleComplete(ripple: HTMLElement, state: RippleState): void {
		if (!state.isPressed) {
			state.animation = "exiting";
			const controls = animateExit(ripple, () => {
				cleanupAnimation(state.id);
				ripple.remove();
			});
			activeAnimations.set(state.id, controls);
			return;
		}
		state.isAnimationEnded = true;
	}

	function startRipple(x: number, y: number): void {
		if (!element.value)
			return;

		const bounding = element.value.getBoundingClientRect();
		const [ripple, state] = createRipple(x, y, bounding.width, bounding.height);

		element.value.append(ripple);

		const controls = animateEnter(ripple, () => {
			handleRippleComplete(ripple, state);
		});

		activeAnimations.set(state.id, controls);
	}

	useEventListener(element, "mousedown", (e: MouseEvent) => {
		if (!element.value)
			return;

		const bounding = element.value.getBoundingClientRect();
		const x = centered ? bounding.width / 2 : e.clientX - bounding.x;
		const y = centered ? bounding.height / 2 : e.clientY - bounding.y;

		startRipple(x, y);
	});

	useEventListener(element, "click", (e: PointerEvent) => {
		if (!element.value || e.pointerType)
			return;

		const bounding = element.value.getBoundingClientRect();
		const [ripple, state] = createRipple(
			bounding.width / 2,
			bounding.height / 2,
			bounding.width,
			bounding.height,
		);

		element.value.append(ripple);

		const controls = animateEnter(ripple, () => {
			handleRippleComplete(ripple, state);
		});

		activeAnimations.set(state.id, controls);
		state.isPressed = false;
		controls.speed = speedDelta * 2;
	});

	useEventListener(element, "mouseup", () => {
		if (!element.value)
			return;

		const ripples
			= element.value.querySelectorAll<HTMLSpanElement>("span.ripple");

		ripples.forEach((ripple) => {
			const state = getRippleState(ripple);
			state.isPressed = false;

			if (state.animation !== "entering")
				return;

			const currentControls = activeAnimations.get(state.id);
			if (!currentControls)
				return;

			if (state.isAnimationEnded) {
				state.animation = "exiting";
				state.isAnimationEnded = false;

				const exitControls = animateExit(ripple, () => {
					cleanupAnimation(state.id);
					ripple.remove();
				});

				activeAnimations.set(state.id, exitControls);
			}
			else {
				currentControls.speed = speedDelta * 2;
			}
		});
	});

	// Очистка при размонтировании компонента
	onUnmounted(() => {
		activeAnimations.forEach(controls => controls.cancel());
		activeAnimations.clear();
	});
}

import type { MaybeRefOrGetter, ShallowRef } from "vue";
import type { UseButtonOptions } from "./use-button";
import { useEventListener } from "@vueuse/core";
import {
	computed,

	toRef,
	watchEffect,
} from "vue";
import { useButton } from "./use-button";

export type UseToggleButtonOptions = {
	isToggleable: Readonly<MaybeRefOrGetter<boolean>>;
	isSelected: Readonly<MaybeRefOrGetter<boolean>>;
	onClick?: () => void;
} & UseButtonOptions;

export function useToggleButton(
	elementRef: Readonly<ShallowRef<HTMLElement | null>>,
	{
		isToggleable: isToggleableMaybeRefOrGetter,
		isSelected: isSelectedMaybeRefOrGetter,
		onClick = () => {},
		...options
	}: UseToggleButtonOptions,
) {
	const element = computed<HTMLElement | null>(() => {
		if (elementRef.value && "$el" in elementRef.value) {
			return elementRef.value.$el as HTMLElement | null;
		}
		return elementRef.value;
	});

	const isToggleable = toRef(isToggleableMaybeRefOrGetter);
	const isSelected = toRef(isSelectedMaybeRefOrGetter);

	const button = useButton(elementRef, options);

	watchEffect(() => {
		if (!element.value)
			return;
		if (!isToggleable.value) {
			element.value.removeAttribute("aria-pressed");
			return;
		}
		if (!element.value.hasAttribute("aria-checked"))
			element.value.setAttribute("aria-pressed", `${isSelected.value}`);
	});

	useEventListener(elementRef, "click", () => {
		onClick();
	});

	return button;
}

export type Duration = number;

